// src/main.ts
function getChildByClass(parent, cls) {
  for (const child of parent.children) {
    if (child.classList.contains(cls)) {
      return child;
    }
  }
  return null;
}
var classPrefix = "queryBuilder";
var ClassContainer = `${classPrefix}Container`;
var ClassFilterGroup = `${classPrefix}FilterGroup`;
var ClassFilterGroupHeader = `${classPrefix}FilterGroupHeader`;
var ClassFilterGroupContent = `${classPrefix}FilterGroupContent`;
var ClassFilterGroupHeaderConditionSelect = `${classPrefix}FilterGroupHeaderHeaderConditionSelect`;
var ClassFilterGroupHeaderConditionOption = `${classPrefix}FilterGroupHeaderHeaderConditionOption`;
var ClassFilterGroupHeaderAddFieldButton = `${classPrefix}FilterGroupHeaderHeaderAddFieldButton`;
var ClassFilterGroupHeaderAddGroupButton = `${classPrefix}FilterGroupHeaderHeaderAddGroupButton`;
var ClassFilterGroupHeaderRemoveButton = `${classPrefix}FilterGroupHeaderHeaderRemoveButton`;
var ClassFilterGroupContentFieldContainer = `${classPrefix}FilterGroupContentFieldContainer`;
var ClassFilterGroupContentFieldInputContainer = `${classPrefix}FilterGroupContentFieldInputContainer`;
var ClassFilterGroupContentFieldInput = `${classPrefix}FilterGroupContentFieldInput`;
var ClassFilterGroupContentFieldAttributeSelect = `${classPrefix}FilterGroupContentFieldAttributeSelect`;
var ClassFilterGroupContentFieldAttributeOption = `${classPrefix}FilterGroupContentFieldAttributeOption`;
var ClassFilterGroupContentFieldOperatorSelect = `${classPrefix}FilterGroupContentFieldOperatorSelect`;
var ClassFilterGroupContentFieldOperatorOption = `${classPrefix}FilterGroupContentFieldOperatorOption`;
var ClassFilterGroupContentFieldRemoveButton = `${classPrefix}FilterGroupContentFieldRemoveButton`;
var defaultAttributeTypes = [
  "number",
  "text",
  "month",
  "date",
  "datetime-local",
  "color",
  "email",
  "password",
  "time",
  "tel",
  "url",
  "week"
];
var defaultFilterOperators = [
  "=",
  "!=",
  "<",
  "<=",
  ">",
  ">=",
  "contains",
  "not contains"
];
var numericOperators = [
  "=",
  "!=",
  "<",
  "<=",
  ">",
  ">="
];
var textOperators = [
  "=",
  "!=",
  "contains",
  "not contains"
];
var conditions = [
  "and",
  "or"
];
var FQB = class {
  cfg;
  nodes;
  attributeTypeSpec;
  rootFilterGroup;
  dom;
  constructor(cfg, dom) {
    if (!cfg.rootNode) {
      this.error("root node not provided, or does not exist");
    }
    if (cfg.attributes.length === 0) {
      cfg.attributes = [];
    }
    this.cfg = cfg;
    if (dom) {
      this.dom = dom;
    } else {
      this.dom = document;
    }
    this.attributeTypeSpec = this.newAttributeTypeSpec();
    this.nodes = this.newNodes();
    this.rootFilterGroup = this.newRootFilterGroup();
  }
  getFilters() {
    return this.filterGroupAppliedFilter(this.rootFilterGroup);
  }
  inputElementFactory(type) {
    return () => {
      const el = this.nodes.filterGroupContentFieldInputFallback();
      el.type = type;
      return el;
    };
  }
  newAttributeTypeSpec() {
    const defaultATS = [
      // Numeric & Range-based
      {
        attributeType: "number",
        operators: numericOperators,
        input: this.inputElementFactory("number")
      },
      //  // Textual (Exact match + Partial match)
      {
        attributeType: "text",
        operators: textOperators,
        input: this.inputElementFactory("text")
      },
      {
        attributeType: "email",
        operators: textOperators,
        input: this.inputElementFactory("email")
      },
      {
        attributeType: "url",
        operators: textOperators,
        input: this.inputElementFactory("url")
      },
      {
        attributeType: "tel",
        operators: textOperators,
        input: this.inputElementFactory("tel")
      },
      {
        attributeType: "password",
        operators: [
          "=",
          "!="
        ],
        input: this.inputElementFactory("password")
      },
      // Temporal (Date/Time)
      {
        attributeType: "date",
        operators: numericOperators,
        input: this.inputElementFactory("date")
      },
      {
        attributeType: "month",
        operators: numericOperators,
        input: this.inputElementFactory("month")
      },
      {
        attributeType: "week",
        operators: numericOperators,
        input: this.inputElementFactory("week")
      },
      {
        attributeType: "time",
        operators: numericOperators,
        input: this.inputElementFactory("time")
      },
      {
        attributeType: "datetime-local",
        operators: [
          "=",
          "!=",
          "<",
          "<=",
          ">",
          ">="
        ],
        input: this.inputElementFactory("datetime-local")
      },
      // Categorical / Special
      {
        attributeType: "color",
        operators: [
          "=",
          "!="
        ],
        input: this.inputElementFactory("color")
      }
    ];
    if (!this.cfg.attributeTypeSpec) {
      return defaultATS;
    }
    const ats = [
      ...this.cfg.attributeTypeSpec
    ];
    for (const d of defaultATS) {
      if (ats.find((a) => a.attributeType === d.attributeType)) {
        continue;
      }
      ats.push(d);
    }
    return ats;
  }
  elementFactory(type, className, provided) {
    return () => {
      let element = this.dom.createElement(type);
      if (provided) {
        element = provided();
      }
      element.classList.add(`${className}`);
      return element;
    };
  }
  newNodes() {
    return {
      container: this.elementFactory("div", ClassContainer, this.cfg.nodes?.container),
      // FilterGroup
      filterGroup: this.elementFactory("div", ClassFilterGroup, this.cfg.nodes?.filterGroup),
      filterGroupHeader: this.elementFactory("div", ClassFilterGroupHeader, this.cfg.nodes?.filterGroupHeader),
      filterGroupContent: this.elementFactory("div", ClassFilterGroupContent, this.cfg.nodes?.filterGroupContent),
      // FilterGroupHeader
      filterGroupHeaderConditionSelect: this.elementFactory("select", ClassFilterGroupHeaderConditionSelect, this.cfg.nodes?.filterGroupHeaderConditionSelect),
      filterGroupHeaderConditionOption: this.elementFactory("option", ClassFilterGroupHeaderConditionOption, this.cfg.nodes?.filterGroupHeaderConditionOption),
      filterGroupHeaderAddFieldButton: this.elementFactory("button", ClassFilterGroupHeaderAddFieldButton, this.cfg.nodes?.filterGroupHeaderAddFieldButton),
      filterGroupHeaderAddGroupButton: this.elementFactory("button", ClassFilterGroupHeaderAddGroupButton, this.cfg.nodes?.filterGroupHeaderAddGroupButton),
      filterGroupHeaderRemoveButton: this.elementFactory("button", ClassFilterGroupHeaderRemoveButton, this.cfg.nodes?.filterGroupHeaderRemoveButton),
      filterGroupContentFieldContainer: this.elementFactory("div", ClassFilterGroupContentFieldContainer, this.cfg.nodes?.filterGroupContentFieldContainer),
      filterGroupContentFieldInputContainer: this.elementFactory("span", ClassFilterGroupContentFieldInputContainer, this.cfg.nodes?.filterGroupContentFieldInputContainer),
      filterGroupContentFieldInputFallback: this.elementFactory("input", ClassFilterGroupContentFieldInput, this.cfg.nodes?.filterGroupContentFieldInputFallback),
      filterGroupContentFieldAttributeSelect: this.elementFactory("select", ClassFilterGroupContentFieldAttributeSelect, this.cfg.nodes?.filterGroupContentFieldAttributeSelect),
      filterGroupContentFieldAttributeOption: this.elementFactory("option", ClassFilterGroupContentFieldAttributeOption, this.cfg.nodes?.filterGroupContentFieldAttributeOption),
      filterGroupContentFieldOperatorSelect: this.elementFactory("select", ClassFilterGroupContentFieldOperatorSelect, this.cfg.nodes?.filterGroupContentFieldOperatorSelect),
      filterGroupContentFieldOperatorOption: this.elementFactory("option", ClassFilterGroupContentFieldOperatorOption, this.cfg.nodes?.filterGroupContentFieldOperatorOption),
      filterGroupContentFieldRemoveButton: this.elementFactory("button", ClassFilterGroupContentFieldRemoveButton, this.cfg.nodes?.filterGroupContentFieldRemoveButton)
    };
  }
  collectFilters(filterGroup) {
    const applied = [];
    const filterGroupContent = getChildByClass(filterGroup, ClassFilterGroupContent);
    if (!filterGroupContent) {
      this.error("no filter group content found");
    }
    for (const child of filterGroupContent.children) {
      if (child.classList.contains(ClassFilterGroup)) {
        applied.push(this.filterGroupAppliedFilter(child));
      } else if (child.classList.contains(ClassFilterGroupContentFieldContainer)) {
        applied.push(this.collectFieldToAppliedFilter(child));
      } else {
        this.error("unrecognized child of filterGroup - not a group or field container");
      }
    }
    return applied;
  }
  filterGroupAppliedFilter(filterGroup) {
    const header = getChildByClass(filterGroup, ClassFilterGroupHeader);
    if (!header) {
      this.error("no filter group header found");
    }
    const condition = getChildByClass(header, ClassFilterGroupHeaderConditionSelect);
    if (!condition) {
      this.error("no condition select element found");
    }
    return {
      condition: condition.value,
      children: this.collectFilters(filterGroup)
    };
  }
  collectFieldToAppliedFilter(ch) {
    const attribute = getChildByClass(ch, ClassFilterGroupContentFieldAttributeSelect);
    const operator = getChildByClass(ch, ClassFilterGroupContentFieldOperatorSelect);
    const inputContainer = getChildByClass(ch, ClassFilterGroupContentFieldInputContainer);
    if (!attribute || !operator || !inputContainer) {
      this.error("failed to collect attribute, operator and field");
    }
    const input = getChildByClass(inputContainer, ClassFilterGroupContentFieldInput);
    return {
      attribute: attribute.value,
      operator: operator.value,
      value: input.value
    };
  }
  error(msg) {
    throw new Error(`queryBuilder: ${msg}`);
  }
  newRootFilterGroup() {
    const container = this.nodes.container();
    this.cfg.rootNode.appendChild(container);
    return this.newFilterGroup(false, container);
  }
  newFilterGroup(removable, parent) {
    const filterGroupContainer = this.newFilterGroupContainer();
    const filterGroupHeader = this.newFilterGroupHeader();
    const filterGroupContent = this.newFilterGroupContent();
    filterGroupContainer.appendChild(filterGroupHeader);
    filterGroupContainer.appendChild(filterGroupContent);
    const andOr = this.newFilterGroupHeaderAndOr();
    const addField = this.newFilterGroupHeaderAddField();
    const addGroup = this.newFilterGroupHeaderAddGroup();
    const remove = this.newFilterGroupHeaderRemove(removable);
    filterGroupHeader.appendChild(andOr);
    filterGroupHeader.appendChild(addField);
    filterGroupHeader.appendChild(addGroup);
    filterGroupHeader.appendChild(remove);
    addField.addEventListener("click", () => {
      this.newFilterGroupField(filterGroupContent);
    });
    remove.addEventListener("click", () => {
      parent.removeChild(filterGroupContainer);
    });
    addGroup.addEventListener("click", () => {
      this.newFilterGroup(true, filterGroupContent);
    });
    parent.appendChild(filterGroupContainer);
    return filterGroupContainer;
  }
  newFilterGroupContainer() {
    const filterGroup = this.nodes.filterGroup();
    return filterGroup;
  }
  newFilterGroupContent() {
    const filterGroupContent = this.nodes.filterGroupContent();
    return filterGroupContent;
  }
  newFilterGroupField(parent) {
    const container = this.nodes.filterGroupContentFieldContainer();
    const selectAttribute = this.nodes.filterGroupContentFieldAttributeSelect();
    for (const opt of this.cfg.attributes) {
      const option = this.nodes.filterGroupContentFieldAttributeOption();
      option.value = opt.name;
      option.innerText = opt.name;
      selectAttribute.appendChild(option);
    }
    const selectOperator = this.nodes.filterGroupContentFieldOperatorSelect();
    const inputContainer = this.nodes.filterGroupContentFieldInputContainer();
    this.setInputAndOperatorsForAttribute(selectAttribute.value, inputContainer, selectOperator);
    selectAttribute.addEventListener("change", (e) => {
      if (e?.target) {
        const t = e.target;
        this.setInputAndOperatorsForAttribute(t.value, inputContainer, selectOperator);
      }
    });
    const remove = this.nodes.filterGroupContentFieldRemoveButton();
    remove.addEventListener("click", () => {
      parent.removeChild(container);
    });
    container.appendChild(selectAttribute);
    container.appendChild(selectOperator);
    container.appendChild(inputContainer);
    container.appendChild(remove);
    parent.appendChild(container);
    return container;
  }
  newFilterGroupHeader() {
    const filterGroupHeader = this.nodes.filterGroupHeader();
    return filterGroupHeader;
  }
  newFilterGroupHeaderAddField() {
    const btn = this.nodes.filterGroupHeaderAddFieldButton();
    return btn;
  }
  newFilterGroupHeaderAddGroup() {
    const btn = this.nodes.filterGroupHeaderAddGroupButton();
    return btn;
  }
  newFilterGroupHeaderRemove(removable) {
    const btn = this.nodes.filterGroupHeaderRemoveButton();
    btn.disabled = !removable;
    return btn;
  }
  newFilterGroupHeaderAndOr() {
    const andOr = this.nodes.filterGroupHeaderConditionSelect();
    for (const opt of conditions) {
      const option = this.nodes.filterGroupHeaderConditionOption();
      option.value = opt;
      option.innerText = opt;
      andOr.appendChild(option);
    }
    return andOr;
  }
  setInputAndOperatorsForAttribute(attrName, inputContainer, select) {
    let attributeType = "text";
    const attribute = this.cfg.attributes.find((a) => a.name === attrName);
    if (attribute) {
      if (defaultAttributeTypes.includes(attribute.type)) {
        attributeType = attribute.type;
      }
    }
    let ops = defaultFilterOperators;
    const f = this.attributeTypeSpec.find((a) => a.attributeType == attributeType);
    if (f) {
      ops = f.operators;
      const newInput = f.input();
      newInput.classList.add(ClassFilterGroupContentFieldInput);
      inputContainer.replaceChildren(newInput);
    } else {
      inputContainer.replaceChildren(this.nodes.filterGroupContentFieldInputFallback());
    }
    select.innerHTML = "";
    for (const opt of ops) {
      const option = this.nodes.filterGroupContentFieldOperatorOption();
      option.value = opt;
      option.innerText = opt;
      select.appendChild(option);
    }
  }
};
export {
  ClassContainer,
  ClassFilterGroup,
  ClassFilterGroupContent,
  ClassFilterGroupContentFieldAttributeOption,
  ClassFilterGroupContentFieldAttributeSelect,
  ClassFilterGroupContentFieldContainer,
  ClassFilterGroupContentFieldInput,
  ClassFilterGroupContentFieldInputContainer,
  ClassFilterGroupContentFieldOperatorOption,
  ClassFilterGroupContentFieldOperatorSelect,
  ClassFilterGroupContentFieldRemoveButton,
  ClassFilterGroupHeader,
  ClassFilterGroupHeaderAddFieldButton,
  ClassFilterGroupHeaderAddGroupButton,
  ClassFilterGroupHeaderConditionOption,
  ClassFilterGroupHeaderConditionSelect,
  ClassFilterGroupHeaderRemoveButton,
  FQB,
  getChildByClass
};
